"""Original dialysis chapter: principles, prescription and vascular access."""
from qbank_authoring import question,ref,finalize
AK=ref('KDIGO Clinical Practice Guideline for Acute Kidney Injury, 2012','https://kdigo.org/wp-content/uploads/2016/10/KDIGO-2012-AKI-Guideline-English.pdf')
HD=ref('KDOQI Hemodialysis Adequacy: 2015 Update','https://www.sciencedirect.com/science/article/pii/S0272638615010197')
VA=ref('KDOQI Vascular Access: 2019 Update','https://www.kidney.org/sites/default/files/2026-07/2019-kdoqi-guideline-vascular-access.pdf')
PD=ref('ISPD Peritonitis Recommendations: 2022 Update','https://journals.sagepub.com/doi/pdf/10.1177/08968608221080586')
PG=ref('ISPD Guidelines: Goal-Directed PD, Membrane Dysfunction and Catheter Infection','https://ispd.org/guidelines/')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))

q('A patient with severe AKI has pulmonary edema and hypoxemia despite appropriate diuretic treatment. Which finding most strongly supports urgent kidney replacement therapy?', 'Life-threatening fluid overload refractory to medical treatment',[
 ('Creatinine exceeding a single universal threshold','Creatinine alone does not define an urgent indication.'),('Oliguria for two hours without other abnormalities','The duration and overall trajectory require assessment.'),('Isolated asymptomatic mild hyperphosphatemia','This usually permits medical management.')],
 'Treat complications rather than a creatinine number', '**Refractory pulmonary edema is an emergency indication for KRT.**',['Urgent indications also include dangerous refractory electrolyte or acid-base disturbances.','The severity of respiratory compromise determines urgency.'], '**Stabilize breathing while arranging definitive fluid removal.**',['Select a modality compatible with circulation and available expertise.','Continue evaluating the reversible AKI cause.'],[['Refractory pulmonary edema','Urgent KRT consideration'],['Creatinine alone','Insufficient trigger'],['Clinical trajectory','Essential context']],[AK],'clinical_scenario')
q('Which transport mechanism primarily removes small water-soluble solutes during conventional hemodialysis?', 'Diffusion down a concentration gradient',[
 ('Convection alone without dialysate','That describes hemofiltration rather than conventional diffusive HD.'),('Active tubular secretion across the membrane','Dialyzer membranes do not contain functioning tubules.'),('Adsorption as the principal mechanism for urea','Adsorption is not the dominant conventional urea-clearance mechanism.')],
 'Different transport mechanisms clear solutes differently', '**Diffusion transfers solutes between blood and dialysate.**',['The gradient, membrane and flow rates affect clearance.','Convection instead carries solutes with filtered water.'], '**Distinguish solute clearance from net fluid removal.**',['Ultrafiltration is pressure driven.','A combined modality can use diffusion and convection.'],[['HD','Predominantly diffusion'],['Hemofiltration','Convection'],['Net ultrafiltration','Fluid removal']],[HD,AK])
q('What is the principal solute transport mechanism of continuous venovenous hemofiltration?', 'Solvent drag accompanying ultrafiltration',[
 ('Diffusion into dialysate as the sole mechanism','Pure CVVH uses replacement fluid rather than a dialysate-based diffusive prescription.'),('Active sodium pumping by the filter','Transport is physical rather than cellular.'),('Selective urea binding to albumin','Urea is not removed through albumin binding.')],
 'Convection couples solute movement to water flux', '**CVVH removes plasma water and its permeable solutes.**',['Replacement fluid prevents excessive net volume loss.','Pre-filter dilution reduces effective solute clearance for a given effluent rate.'], '**Interpret the actual circuit configuration.**',['CVVHD adds diffusive dialysate clearance.','CVVHDF combines diffusive and convective components.'],[['CVVH','Convection'],['CVVHD','Diffusion'],['CVVHDF','Both']],[AK])
q('A ventilated patient with AKI requires high vasopressor doses and gradual fluid removal. Which KRT strategy is generally favored if available?', 'Continuous KRT with carefully titrated net ultrafiltration',[
 ('Rapid high-volume intermittent ultrafiltration regardless of perfusion','Abrupt fluid shifts may worsen instability.'),('Withhold KRT until vasopressors are stopped','Life-threatening complications may require treatment during shock.'),('Choose CRRT because it guarantees a mortality advantage','A universal survival advantage has not been established.')],
 'Hemodynamic tolerance influences modality selection', '**Continuous treatment permits slower fluid and solute changes.**',['Prolonged intermittent therapies may also suit selected patients.','The prescription must account for resuscitation and ongoing inputs.'], '**Reassess net fluid removal against perfusion.**',['A modality label does not ensure safe ultrafiltration.','Choose locally deliverable therapy without an unsupported survival claim.'],[['Shock','Slower treatment often preferred'],['Fluid removal','Individualized'],['Mortality','No universal CRRT superiority']],[AK],'clinical_scenario')
q('Which delivered CRRT effluent dose is recommended by the finalized KDIGO 2012 AKI guideline for most adults?', '20–25 mL/kg/hour',[
 ('5–10 mL/kg/hour','This is below the recommended usual delivered range.'),('50–60 mL/kg/hour routinely','Higher intensity has not shown routine outcome benefit.'),('100 mL/kg/hour routinely','This is not a standard maintenance prescription.')],
 'Prescribed dose and delivered dose differ', '**Downtime can reduce delivered clearance below the prescription.**',['A somewhat higher prescription may be needed to achieve the delivery target.','Electrolytes, temperature and drug clearance need surveillance.'], '**Assess treatment delivery rather than the order alone.**',['Include interruptions and filter performance.','Special situations may require a different prescription.'],[['Usual delivered target','20–25 mL/kg/hour'],['Prescription','Accounts for downtime'],['Higher intensity','Not routinely better']],[AK])
q('During regional citrate anticoagulation, which action produces anticoagulation within the extracorporeal circuit?', 'Chelation of ionized calcium',[
 ('Direct inhibition of thrombin by citrate','Citrate does not act as a direct thrombin inhibitor.'),('Suppression of platelet production','This is not citrate action.'),('Irreversible inhibition of vitamin K recycling','This describes vitamin K antagonism.')],
 'Regional anticoagulation depends on calcium removal', '**Citrate lowers circuit ionized calcium and impairs coagulation.**',['Systemic calcium is replaced according to protocol.','Metabolized citrate can contribute bicarbonate.'], '**Monitor both circuit and patient.**',['Follow systemic ionized calcium and acid-base status.','Impaired citrate metabolism can cause accumulation and increasing calcium requirements.'],[['Circuit','Low ionized calcium'],['Patient','Calcium replacement'],['Safety','Calcium and acid-base monitoring']],[AK])
q('A CRRT patient on citrate develops worsening systemic ionized hypocalcemia, rising calcium infusion needs and a rising total-to-ionized calcium ratio. What complication should be suspected?', 'Citrate accumulation',[
 ('Uncomplicated metabolic alkalosis from complete citrate metabolism','That does not explain the accumulation pattern.'),('Excess systemic heparin effect','Heparin does not produce this calcium signature.'),('Simple dialysate potassium depletion','This cannot account for the calcium ratio.')],
 'A discordant calcium pattern can reveal citrate retention', '**Accumulated calcium-citrate complexes raise total calcium relative to ionized calcium.**',['Shock and impaired metabolism increase risk.','A ratio around or above 2.5 is a warning sign in the appropriate context.'], '**Review or stop citrate according to the clinical protocol.**',['Correct ionized calcium and evaluate perfusion.','Interpret the ratio with acid-base findings and serial trends.'],[['Ionized calcium','Falls'],['Calcium requirement','Rises'],['Total/ionized ratio','May rise above 2.5']],[AK],'clinical_scenario')
q('For thrice-weekly maintenance hemodialysis, which pair matches the KDOQI 2015 single-pool Kt/V target and minimum delivered dose?', 'Target 1.4; minimum delivered 1.2 per session',[
 ('Target 0.8; minimum 0.6','Both values are below the usual recommendation.'),('Target 1.2; minimum 1.0','The minimum delivered value is too low.'),('Target 2.3; minimum 2.1 per session','These resemble weekly standard Kt/V targets for other schedules, not per-session spKt/V.')],
 'Specify the metric and schedule', '**Single-pool Kt/V is a per-session small-solute dose measure.**',['K is clearance, t is treatment duration and V is urea distribution volume.','Residual kidney function and alternative schedules require additional interpretation.'], '**Adequacy also includes symptoms and fluid control.**',['An acceptable urea number does not ensure adequate volume management.','Check sampling and missed treatment when delivery is low.'],[['Thrice-weekly spKt/V target','1.4'],['Minimum delivered','1.2'],['Overall adequacy','Broader than urea']],[HD])
q('A patient repeatedly misses the last hour of dialysis. Kt/V is low despite an apparently functioning access. Which intervention most directly addresses the likely cause?', 'Restore the prescribed treatment duration and investigate barriers to completing sessions',[
 ('Increase erythropoietin without changing dialysis','This does not restore lost clearance time.'),('Assume every low Kt/V proves access stenosis','Time loss is an evident alternative cause.'),('Lower the adequacy target to match delivered treatment','This accepts underdelivery without resolving its cause.')],
 'Clearance time is a modifiable component of dose', '**Shortening treatment reduces delivered Kt/V.**',['It also compresses necessary fluid removal into less time.','Cramps, transport and patient priorities may underlie early termination.'], '**Use a practical shared treatment plan.**',['Evaluate access performance if dose remains low.','Review prescribed versus actual time and flow.'],[['Dose component','Treatment duration'],['Potential consequence','High ultrafiltration rate'],['Response','Address barriers and remeasure']],[HD],'clinical_scenario')
q('Which principle best reflects current vascular access selection for maintenance dialysis?', 'An individualized ESKD Life-Plan integrating modality, prognosis, anatomy and future access options',[
 ('A fistula is mandatory in every patient regardless of circumstances','KDOQI moved away from an indiscriminate fistula-first approach.'),('A tunneled catheter is always the preferred permanent access','Catheters carry important infection and dysfunction risks.'),('Choose access without considering transplant or PD plans','Future modality choices affect access decisions.')],
 'Access choice should serve the patient’s treatment course', '**A suitable fistula can provide durable access but requires maturation.**',['A graft may be appropriate when fistula maturation is unlikely or timing matters.','Catheters may be necessary while definitive access is established.'], '**Preserve future vascular sites.**',['Assess vessels, expected use and patient preference.','Revisit the plan when health or modality changes.'],[['Fistula','Maturation and anatomy matter'],['Graft','Earlier use may be useful'],['Catheter','Infection and patency concerns']],[VA])
q('A mature fistula has reduced dialysis blood flow, prolonged post-needle bleeding and a high-pitched localized bruit. What is the most appropriate next step?', 'Evaluate for clinically significant access stenosis',[
 ('Angioplasty solely because routine imaging shows an asymptomatic narrowing','Clinical indicators are central to intervention decisions.'),('Ignore the findings if one Kt/V value is normal','These are access dysfunction indicators.'),('Diagnose steal syndrome as the best fit','Steal primarily causes distal ischemic symptoms.')],
 'Clinical monitoring identifies access dysfunction', '**Outflow stenosis can cause prolonged bleeding and abnormal examination findings.**',['Low blood flow or declining delivered dose can be additional clues.','Anatomic confirmation guides treatment.'], '**Treat a culprit lesion in its clinical context.**',['Avoid preemptive procedures for an isolated surveillance abnormality without clinical indication.','Assess for thrombosis risk and alternative causes.'],[['Stenosis','Abnormal bruit/flow/bleeding'],['Steal','Distal ischemia'],['Intervention','Clinical plus anatomic evidence']],[VA],'clinical_scenario')
q('After fistula creation a patient has a painful cold hand, weak distal pulse and symptoms worsened during dialysis. Which complication is most likely?', 'Access-associated distal ischemia',[
 ('Central venous stenosis as the best explanation','That more often produces swelling and collateral veins.'),('Isolated venous needle infiltration','This causes local swelling or bruising rather than persistent distal ischemia.'),('Dialysis disequilibrium syndrome','This is a neurological osmotic complication.')],
 'Access flow can compromise distal perfusion', '**Hand ischemia requires prompt severity assessment.**',['Diabetes and pre-existing arterial disease increase risk.','Severe rest pain, tissue injury or neurological deficit needs urgent specialist action.'], '**Protect both limb and appropriate dialysis access.**',['Examine arterial inflow and access hemodynamics.','The corrective procedure depends on anatomy and severity.'],[['Ischemia','Cold painful distal limb'],['Venous obstruction','Swelling/collaterals'],['Urgency','Threatened tissue or nerve function']],[VA],'clinical_scenario')
q('An HD patient with a previous subclavian catheter develops ipsilateral arm swelling and prominent chest-wall veins after fistula creation. Which lesion is most likely?', 'Central venous stenosis',[
 ('Arterial steal as the primary lesion','Cold ischemic fingers are more typical than venous congestion.'),('A small stable needle-site hematoma','It does not explain widespread venous collaterals.'),('Dialyzer membrane allergy','That produces an acute dialysis reaction, not this local venous pattern.')],
 'Prior central catheters can compromise venous outflow', '**A high-flow access can unmask central venous obstruction.**',['Catheter history and venous collaterals are important clues.','The evaluation should define the central venous anatomy.'], '**Preserve future access options.**',['Avoid unnecessary subclavian catheterization in patients likely to need HD.','Intervene for clinically significant symptomatic disease.'],[['Risk','Prior central catheter'],['Findings','Arm edema and collaterals'],['Mechanism','Impaired central outflow']],[VA],'clinical_scenario')
q('A fistula loses its usual thrill abruptly and cannot provide dialysis flow. What is the best immediate approach?', 'Urgent access assessment for thrombosis and salvage, with alternative dialysis access if urgently needed',[
 ('Continue repeated blind cannulation of the silent access','This delays definitive evaluation and risks injury.'),('Wait several weeks to see whether flow returns','Delay reduces salvage opportunities.'),('Diagnose access infection without examination or cultures','Loss of flow is not specific for infection.')],
 'Loss of thrill can signal access thrombosis', '**Rapid evaluation may preserve the access.**',['A causative stenosis often accompanies thrombosis.','Dialysis urgency determines whether temporary access is also required.'], '**Evaluate the whole access circuit.**',['Restore flow and address the underlying lesion where appropriate.','Document recurrent events in the Life-Plan.'],[['New absent thrill','Suspect thrombosis'],['Priority','Timely salvage assessment'],['Underlying cause','Often stenosis']],[VA],'clinical_scenario')
q('Which factor most directly increases the risk of intradialytic hypotension?', 'Ultrafiltration exceeding plasma refill and cardiovascular compensation',[
 ('An isolated rise in phosphate without fluid removal','This is not the principal acute hemodynamic mechanism.'),('A higher hemoglobin within the normal range alone','This does not explain typical volume-related hypotension.'),('Reduced dialysate glucose as the universal cause','Several factors matter; volume removal is central.')],
 'Fluid removal must match circulatory tolerance', '**Rapid intravascular depletion can lower cardiac filling.**',['Autonomic dysfunction and cardiac disease reduce compensation.','Meals, medications and thermal effects can contribute.'], '**Review target weight and the ultrafiltration prescription.**',['Longer or additional treatments can reduce required hourly removal.','During an episode assess for sepsis, bleeding and cardiac causes as indicated.'],[['Main mismatch','Removal versus refill'],['Risk modifiers','Cardiac/autonomic disease'],['Prevention','Individualized rate and time']],[HD])
q('Headache, confusion and seizures develop during the first dialysis of a markedly azotemic patient. Which mechanism best fits dialysis disequilibrium syndrome?', 'A rapid plasma urea fall creates an osmotic gradient favoring brain water entry',[
 ('Chronic beta-2-microglobulin deposition','This produces a late musculoskeletal complication.'),('Distal hand hypoperfusion from the access','This does not explain global neurological deterioration.'),('Immune-complex deposition in the dialyzer','This is not the accepted osmotic mechanism.')],
 'Avoid abrupt osmotic change in high-risk initiation', '**Brain solute equilibration can lag behind blood clearance.**',['First treatments and severe azotemia increase risk.','Hypoglycemia, hemorrhage and other acute neurological causes still require exclusion.'], '**Use a cautious initial clearance prescription.**',['Reduce or stop treatment and stabilize an acute event.','Specialist management may include measures against cerebral edema.'],[['Setting','First dialysis/severe azotemia'],['Mechanism','Osmotic brain water shift'],['Prevention','Gradual initial clearance']],[AK,HD],'clinical_scenario')
q('A dialysis patient develops carpal tunnel syndrome, shoulder pain and destructive arthropathy after many years of treatment. Which deposited protein is characteristic?', 'Beta-2-microglobulin',[
 ('Serum amyloid A in every case','That is associated with chronic inflammatory AA amyloid.'),('Immunoglobulin light chain as the defining dialysis deposit','That characterizes AL amyloid.'),('Transthyretin as the usual dialysis-related protein','ATTR has a different disease mechanism.')],
 'Dialysis-related amyloid favors osteoarticular tissues', '**Beta-2-microglobulin accumulates when kidney clearance is severely impaired.**',['Long dialysis vintage is a typical context.','Other amyloid types require different evaluation.'], '**Identify the protein rather than treating all amyloid as AL.**',['Assess compressive and structural complications.','Modern dialysis strategies and transplantation affect exposure over time.'],[['Dialysis-related','Beta-2-microglobulin'],['AL','Light chain'],['AA','Serum amyloid A']],[HD])
q('Dyspnea, wheeze and hypotension begin within minutes of connecting a new dialyzer. What is the immediate management priority?', 'Stop dialysis, assess an acute hypersensitivity reaction and provide emergency treatment',[
 ('Return all circuit blood automatically before evaluating a severe reaction','Reinfusion can aggravate some severe dialyzer reactions.'),('Increase blood flow to clear the allergen faster','This can worsen exposure.'),('Treat as dialysis disequilibrium without considering anaphylaxis','The immediate respiratory and circulatory pattern suggests a reaction.')],
 'An early dialysis reaction can be life-threatening', '**Airway and circulation take priority.**',['Potential triggers include membrane, sterilant and administered medications.','Anaphylaxis requires the appropriate emergency protocol including epinephrine when indicated.'], '**Investigate and avoid the implicated exposure.**',['Do not automatically return circuit blood in a suspected severe reaction.','Document the exact membrane and concurrent drugs.'],[['Timing','Often early after connection'],['Features','Wheeze/hypotension'],['Action','Stop exposure and resuscitate']],[HD],'clinical_scenario')
q('A hemodialysis patient has fever and rigors during use of a tunneled catheter. Which initial strategy is appropriate?', 'Obtain appropriate blood cultures promptly and start empiric therapy guided by severity and local organisms',[
 ('Remove every stable catheter without cultures or an access plan','Removal decisions depend on organism, severity and complications.'),('Use topical exit-site antibiotic alone for suspected bloodstream infection','Systemic infection requires systemic assessment and therapy.'),('Wait for the next routine session before investigating','Sepsis and metastatic infection may progress.')],
 'Separate catheter bloodstream infection from isolated exit-site disease', '**Cultures guide organism-specific treatment and catheter strategy.**',['Hemodynamic instability requires immediate sepsis care.','Persistent bacteremia or high-risk organisms strengthen indications for catheter removal.'], '**Assess for endocarditis or other metastatic infection when indicated.**',['Obtain cultures without delaying urgent treatment.','Select salvage only within an appropriate specialist protocol.'],[['Systemic illness','Bloodstream infection work-up'],['Exit-site signs alone','Different assessment'],['Removal','Organism and complication dependent']],[VA],'clinical_scenario')
q('Why should residual kidney function be considered when prescribing maintenance dialysis?', 'It contributes continuous solute and fluid clearance and affects the total treatment prescription',[
 ('Urine volume proves normal native solute clearance','Urine volume and clearance are not interchangeable.'),('Residual clearance makes scheduled assessment unnecessary','Residual function can decline and must be reassessed.'),('Any urine output eliminates the need for dialysis','Clinical adequacy and measured clearance determine needs.')],
 'Residual function is valuable but must be quantified', '**Native clearance can materially contribute to total adequacy.**',['Urine collection can help measure residual clearance.','Avoid assuming that a diuretic-induced urine volume equals recovery.'], '**Adapt the prescription as native function changes.**',['Monitor volume, symptoms and biochemical control.','Incremental schedules require appropriate selection and follow-up.'],[['Urine volume','Not equivalent to clearance'],['Residual clearance','Contributes to total dose'],['Monitoring','Needed over time']],[HD,PG])
